def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            if math.isfinite(x):
                y.append(max(0.0, x))
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    p = 24 if 'hour' in frequency.lower() else (7 if 'day' in frequency.lower() else 1)
    if len(y) < p:
        return [float(statistics.median(y[-min(5, len(y)):]))] * h
    count = min(3, len(y) // p)
    cycles = [y[len(y) - (j + 1) * p:len(y) - j * p] for j in range(count)]
    profile = []
    for phase in range(p):
        vals = [c[phase] for c in cycles]
        if len(vals) >= 2 and vals[0] == 0.0 and vals[1] == 0.0:
            profile.append(0.0)
        else:
            center = statistics.median(vals)
            profile.append(float(0.5 * vals[0] + 0.5 * center))
    return [profile[k % p] for k in range(h)]

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            if math.isfinite(x):
                y.append(max(0.0, x))
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    p = 24 if 'hour' in frequency.lower() else (7 if 'day' in frequency.lower() else 1)
    if len(y) < p:
        return [float(statistics.median(y[-min(5, len(y)):]))] * h
    count = min(3, len(y) // p)
    cycles = [y[len(y) - (j + 1) * p:len(y) - j * p] for j in range(count)]
    bounds = []
    for c in cycles:
        active = [i for i, x in enumerate(c) if x > 0.0]
        if active:
            bounds.append((active[0], active[-1]))
    if not bounds:
        return [0.0] * h
    start = int(round(statistics.median([b[0] for b in bounds])))
    end = int(round(statistics.median([b[1] for b in bounds])))
    profile = [0.0] * p
    for phase in range(max(0, start), min(p - 1, end) + 1):
        vals = [c[phase] for c in cycles if c[phase] > 0.0]
        if len(vals) >= max(1, min(2, count)):
            profile[phase] = float(statistics.median(vals))
    return [profile[k % p] for k in range(h)]

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            if math.isfinite(x):
                y.append(max(0.0, x))
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    p = 24 if 'hour' in frequency.lower() else (7 if 'day' in frequency.lower() else 1)
    if len(y) < 2 * p:
        if len(y) >= p:
            base = y[-p:]
            return [base[k % p] for k in range(h)]
        return [float(statistics.median(y[-min(5, len(y)):]))] * h
    count = min(3, len(y) // p)
    cycles = [y[len(y) - (j + 1) * p:len(y) - j * p] for j in range(count)]
    required = 2
    profile = []
    for phase in range(p):
        positive = [c[phase] for c in cycles if c[phase] > 0.0]
        if len(positive) < required:
            profile.append(0.0)
        else:
            logs = [math.log1p(x) for x in positive]
            profile.append(float(max(0.0, math.expm1(statistics.median(logs)))))
    return [profile[k % p] for k in range(h)]
